<?php
namespace App\Http\Controllers; use App\Domain\Library\Services\LibraryFineService; use App\Models\{LibraryFine,LibraryTransaction}; use App\Support\Tenancy\TenantContext; use Illuminate\Http\Request;
class LibraryFineController extends Controller {public function __construct(private LibraryFineService $service){} public function index(){ $this->authorize('viewAny',LibraryFine::class); return view('library_fines.index',['fines'=>LibraryFine::with('transaction.bookCopy.book','member')->latest()->paginate(20)]);} public function store(Request $r){$r->validate(['library_transaction_id'=>'required|integer','rate_per_day'=>'required|numeric|min:0.01']);$tx=LibraryTransaction::findOrFail($r->library_transaction_id);$this->authorize('create',LibraryFine::class);$fine=$this->service->assess(app(TenantContext::class)->require(),$tx,$r->user(),(float)$r->rate_per_day);return back()->with('success','Fine assessed.');} public function pay(Request $r,LibraryFine $library_fine){$this->authorize('pay',$library_fine);$this->service->pay($library_fine,$r->user(),(string)$r->input('payment_reference'));return back()->with('success','Fine paid.');}}
